<?php

declare(strict_types=1);
require dirname(__DIR__) . '/config/bootstrap.php';
use App\Auth; use App\Database; use App\Services\Provider\MarketerumServiceType; use App\Services\OrderService; use App\Services\Provider\ProviderFactory;
$userId=Auth::requireLogin(); $pdo=Database::connection(); $error=null; $success=null;
$walletStmt=$pdo->prepare('SELECT balance FROM users WHERE id=:id'); $walletStmt->execute([':id'=>$userId]); $wallet=(float)$walletStmt->fetchColumn();
$services=$pdo->query("SELECT * FROM services WHERE status=1 ORDER BY name")->fetchAll();
$selectedId=(int)($_GET['service'] ?? $_POST['service_id'] ?? 0); $selected=null;
foreach($services as $s){if((int)$s['id']===$selectedId){$selected=$s;break;}}
if($_SERVER['REQUEST_METHOD']==='POST'){
    Auth::verifyCsrf($_POST['_csrf'] ?? null);
    if(!$selected){$error='Please select a service.';} else {
        $fields=[]; foreach(['link','quantity','runs','interval','keywords','comments','usernames','hashtags','hashtag','username','media','min','max','posts','old_posts','delay','expiry','answer_number','groups'] as $key){if(isset($_POST[$key])&&trim((string)$_POST[$key])!=='')$fields[$key]=trim((string)$_POST[$key]);}
        if(isset($fields['quantity']))$fields['quantity']=(int)$fields['quantity'];
        try{$orderId=(new OrderService(ProviderFactory::marketerum()))->place($userId,$selectedId,$fields);$success='Order #'.$orderId.' was submitted successfully.';$wallet-=(float)$selected['selling_rate']*((int)($fields['quantity']??0))/1000;}catch(Throwable $e){$error=$e->getMessage();}
    }
}
$fields=$selected?MarketerumServiceType::fields($selected['provider_type']):[];
$labels=['link'=>'Target Link / URL','quantity'=>'Quantity','comments'=>'Comments (one per line)','keywords'=>'Keywords (one per line)','usernames'=>'Usernames (one per line)','hashtags'=>'Hashtags (one per line)','username'=>'Username','media'=>'Media URL','hashtag'=>'Hashtag','groups'=>'Groups (one per line)','answer_number'=>'Poll answer number'];
$currency=$selected['customer_currency']??env('CURRENCY','NGN'); $rate=$selected?(float)$selected['selling_rate']:0; $min=$selected?(int)$selected['min_quantity']:0; $max=$selected?(int)$selected['max_quantity']:0;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New Order | SMM Panel</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="/dashboard.php">SMM Panel</a><a class="btn btn-outline-light btn-sm" href="/wallet.php">Wallet</a></div></nav><main class="container py-4"><div class="row justify-content-center"><div class="col-lg-9"><div class="card border-0 shadow-sm"><div class="card-body p-4"><div class="d-flex justify-content-between"><div><h2>New Order</h2><p class="text-muted">Wallet: <strong><?=htmlspecialchars($currency)?> <?=number_format($wallet,2)?></strong></p></div></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><form method="post" id="orderForm" novalidate><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Auth::csrfToken())?>"><div class="mb-3"><label class="form-label">Service</label><select class="form-select" name="service_id" onchange="location.href='?service='+this.value" required><option value="">Select service</option><?php foreach($services as $s):?><option value="<?= (int)$s['id']?>" <?=$selectedId===(int)$s['id']?'selected':''?>><?=htmlspecialchars(($s['category']??'').' — '.$s['name'].' ('.$s['provider_type'].')')?> — <?=htmlspecialchars($s['customer_currency']??$currency)?> <?=number_format((float)$s['selling_rate'],4)?>/1K</option><?php endforeach;?></select></div><?php if($selected):?><div class="alert alert-light border"><div class="row"><div class="col-md-5"><strong><?=htmlspecialchars($selected['name'])?></strong><div class="small text-muted"><?=htmlspecialchars($selected['provider_type'])?></div></div><div class="col-md-3"><strong>Rate</strong><br><?=htmlspecialchars($currency)?> <?=number_format($rate,4)?> / 1K</div><div class="col-md-4"><strong>Allowed quantity</strong><br><?=number_format($min)?> – <?=number_format($max)?></div></div></div><?php foreach($fields as $field):$isArea=in_array($field,['comments','keywords','usernames','hashtags','groups'],true);?><div class="mb-3"><label class="form-label"><?=htmlspecialchars($labels[$field]??ucfirst(str_replace('_',' ',$field)))?></label><?php if($isArea):?><textarea class="form-control" name="<?=htmlspecialchars($field)?>" rows="5" required></textarea><?php elseif($field==='quantity'):?><input id="quantity" class="form-control" name="quantity" type="number" min="<?=$min?>" max="<?=$max?>" step="1" required><?php else:?><input class="form-control" name="<?=htmlspecialchars($field)?>" type="text" required><?php endif;?></div><?php endforeach;?><div id="chargeBox" class="alert alert-primary d-none"><div class="d-flex justify-content-between"><span>Order charge</span><strong id="chargeText"></strong></div><div class="small mt-1" id="remainingText"></div></div><button id="submitOrder" class="btn btn-primary w-100">Place Order</button><?php endif;?></form></div></div></div></div></main><script>const q=document.getElementById('quantity'),box=document.getElementById('chargeBox'),charge=document.getElementById('chargeText'),remaining=document.getElementById('remainingText'),submit=document.getElementById('submitOrder');const rate=<?=json_encode($rate)?>,wallet=<?=json_encode($wallet)?>,min=<?=json_encode($min)?>,max=<?=json_encode($max)?>,currency=<?=json_encode($currency)?>;function preview(){if(!q)return;const n=Number(q.value);if(!Number.isFinite(n)||n<min||n>max){box.classList.add('d-none');submit.disabled=false;return;}const c=Math.round(rate*n/1000*10000)/10000;const r=Math.round((wallet-c)*100)/100;box.classList.remove('d-none');charge.textContent=currency+' '+c.toFixed(4);remaining.textContent=r>=0?'Remaining wallet balance: '+currency+' '+r.toFixed(2):'Insufficient wallet balance';submit.disabled=r<0;}if(q)q.addEventListener('input',preview);preview();</script></body></html>
